# WN11 CC step c: SMB guest, hardened UNC paths, RPC (3 rules, 4 values) - drafted with Claude
$r="HKLM:\SOFTWARE\Policies\Microsoft\Windows\LanmanWorkstation|AllowInsecureGuestAuth|DWord|0","HKLM:\SOFTWARE\Policies\Microsoft\Windows\NetworkProvider\HardenedPaths|\\*\NETLOGON|String|RequireMutualAuthentication=1, RequireIntegrity=1","HKLM:\SOFTWARE\Policies\Microsoft\Windows\NetworkProvider\HardenedPaths|\\*\SYSVOL|String|RequireMutualAuthentication=1, RequireIntegrity=1","HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\Rpc|RestrictRemoteClients|DWord|1"
foreach($i in $r){$p,$n,$t,$d=$i -split "\|"; if($t -eq "DWord"){$d=[int]$d}; if(-not (Test-Path $p)){New-Item -Path $p -Force | Out-Null}; New-ItemProperty -Path $p -Name $n -Value $d -PropertyType $t -Force | Out-Null; "$n = " + (Get-Item -Path $p).GetValue($n)}
